import sys,numpy as np
sys.path.insert(0,'/opt/tools'); from rcb_client import Robot
r=Robot(); o=r.get_obs(cameras=['scene_cam'],depth=True,video='none'); im=o.last['scene_cam'].astype(float); d=o.last_depth['scene_cam']
hexs=['89a896','899c4f','7d9366','64967c','748577','5c877f','7f7936','976d51','82735d','5c759e','54745d','5c7441','557079','615a58','40598c','435471']
cols=np.array([[int(h[i:i+2],16) for i in (0,2,4)] for h in hexs])
K=np.array(o.meta['cameras']['scene_cam']['intrinsic_cv']); E=np.array(o.meta['cameras']['scene_cam']['extrinsic_cv']);
for i,c in enumerate(cols):
 dist=np.linalg.norm(im[170:260,350:415]-c,axis=2); yy,xx=np.where(dist<45); xx+=350; yy+=170
 if len(xx):
  cx,cy=np.mean(xx),np.mean(yy); mask=(xx-cx)**2+(yy-cy)**2<25
  # use median discrete closest exact RGB samples
  u,v=round(cx),round(cy); z=float(d[v,u]); pc=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z]); pw=np.linalg.inv(E[:,:3])@(pc-E[:,3]);
  print(i+1,'rgb',c.tolist(),'pix',round(cx,1),round(cy,1),'n',len(xx),'depth',z,'world',np.round(pw,4))
 else: print(i+1,'none')
