import sys,numpy as np
from PIL import Image
sys.path.insert(0,'/app/output');from gen import build_strokes,PALETTE_RGB,rgb_to_lab
out=np.array(Image.open('/app/output/canvas_aligned.png').convert('RGB')).astype(float)
_,labels,_=build_strokes(30)
colors=[]
for p in range(16):
 pts=[]
 for r in range(30):
  for c in range(30):
   if labels[r,c]==p:
    u=round((c+.5)*1024/30);v=round((r+.5)*1024/30); pts.extend(out[v-2:v+3,u-2:u+3].reshape(-1,3))
 if pts:
  m=np.median(pts,axis=0); colors.append(m); print(p+1,'ncell',np.sum(labels==p),'canvasRGB',m.round(1),'practiceRGB',PALETTE_RGB[p].tolist(),'target target nearest?')
 else:colors.append(PALETTE_RGB[p]);print(p+1,'none')
np.save('/app/output/canvas_palette.npy',np.array(colors))
